from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

# Формат -> (разделитель, {поле -> название колонки в нижнем регистре}).
_FORMATS: dict[str, tuple[str, dict[str, str]]] = {
    "nova": (",", {"date": "date", "amount": "amount", "description": "description"}),
    "sfera": (";", {"date": "дата", "amount": "сумма", "description": "описание"}),
    "sfera_split": (
        ";",
        {"date": "дата", "description": "описание", "income": "приход", "expense": "расход"},
    ),
}

# Сумма «Сферы»: пробелы (в том числе U+00A0) между группами по три цифры, запятая перед копейками.
_RU_AMOUNT = re.compile(r"(?P<sign>[+-]?)(?P<whole>[0-9]{1,3}(?:\s[0-9]{3})+|[0-9]+)(?:,(?P<frac>[0-9]+))?")
_DMY_DATE = re.compile(r"(?P<day>[0-9]{2})\.(?P<month>[0-9]{2})\.(?P<year>[0-9]{4})")
_JUNK_RECORD = re.compile(r"[\s;,]*")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def normalize_description(text: str) -> str:
    """Описание в виде для сравнения дублей (то же сравнение, что в правилах)."""
    return normalize_text(text)


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Без strict кривые строки попадают в result.errors, остальное импортируется.
    С strict первая кривая строка бросает StatementRowError, и в хранилище ничего не пишется.
    Запись всегда одной пачкой (add_many): либо все добавленные строки, либо ни одной.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    name, index, header_line = _detect(text, fmt)
    delimiter = _FORMATS[name][0]

    # Дубли: сравниваем только с тем, что было в хранилище до импорта, по количеству.
    remaining = Counter(_import_key(tx) for tx in store.all())
    to_add: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    rows = (rec for rec in _records(text, delimiter) if not _is_junk(rec[2]))
    next(rows)  # заголовок уже разобран в _detect
    for line_no, cells, _ in rows:
        try:
            tx = _build(name, cells, index, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        key = _import_key(tx)
        if remaining[key] > 0:
            remaining[key] -= 1
            duplicates += 1
            continue
        to_add.append(tx)

    if to_add:
        store.add_many(to_add)
    logger.info("imported %d transactions from %s (duplicates: %d)", len(to_add), path, duplicates)
    return ImportResult(
        format=name,
        encoding=encoding,
        added=len(to_add),
        duplicates=duplicates,
        errors=errors,
    )


